using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_dd723d03e015492c8fdbe161c489ceb8.Client.Auth;

namespace sv_dd723d03e015492c8fdbe161c489ceb8.Auth;

// Server-side AuthenticationStateProvider that:
//  1. Returns a hardcoded authenticated user (bob@example.com, roles User + Editor).
//  2. Persists the user info into PersistentComponentState so the WASM
//     client can reconstruct the ClaimsPrincipal after the handoff.
public sealed class PersistingServerAuthenticationStateProvider
    : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private static readonly Claim[] _claims =
    {
        new(ClaimTypes.Name, "bob@example.com"),
        new(ClaimTypes.Email, "bob@example.com"),
        new(ClaimTypes.Role, "User"),
        new(ClaimTypes.Role, "Editor"),
    };

    private static readonly AuthenticationState _state = new(
        new ClaimsPrincipal(new ClaimsIdentity(_claims, authenticationType: "Hardcoded")));

    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;

    public PersistingServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentComponentState = persistentComponentState;
        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_state);

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        // Required by IHostEnvironmentAuthenticationStateProvider but we
        // never change state at runtime, so this is intentionally a no-op.
    }

    private Task OnPersistingAsync()
    {
        var userInfo = new UserInfo
        {
            Email = "bob@example.com",
            Roles = new[] { "User", "Editor" },
        };

        _persistentComponentState.PersistAsJson(nameof(UserInfo), userInfo);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

